<?php
namespace qqworld_collector\module\collect_filter; use qqworld_collector\lib; class qqworld_collector_parse_jingyanlib_com_post_content extends lib { var $post_content = array(); public function __construct() { add_filter( 'qqworld-collector-parse-jingyanlib-com-post-content', array($this, 'filter'), 10, 6 ); } public function filter($item, $source_link, $html, $type, $item_args, $download_args) { $json = json_decode($item, true); if ($json) { if (is_string($json['content'])) $answers = json_decode($json['content'], true); else $answers = $json; $list = array(); if (is_array($answers)) { foreach ($answers as $answer) { foreach ($answer as $ans) { foreach ($ans as $type => $con) { switch ($type) { case 'txt': $list[] = '<p>' . $con . '</p>'; break; case 'img': $img = preg_replace('/\?.*/i', '', $con[0]); $list[] = '<p><img src="' . $img . '" /></p>'; break; } } } } } else { $list[] = $json['content']; } if ($list) $item = implode('', $list); } return $item; } } new qqworld_collector_parse_jingyanlib_com_post_content; ?>